       + '--dk-font:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display","Segoe UI Variable Text","Segoe UI","PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;'
